import java.util.Scanner;

public class Main {
    public static int readNumber(Scanner scanner) {
        int val = 0;
        while (true) {
            String token = scanner.next();
            if (token.matches("\\d+")) {
                val = Integer.parseInt(token);
                break;
            }
        }
        return val;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        StringBuilder t = new StringBuilder();
        t.append(s.charAt(0));
        boolean used_at = false;
        int n = s.length();
        s += "\u0001\u0001\u0001\u0001"; // Append special characters
        int i = 1;
        while (i < n) {
            if (s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't' && s.charAt(i + 3) != '\u0001') {
                t.append('.');
                i += 3;
            } else if (s.charAt(i) == 'a' && s.charAt(i + 1) == 't' && !used_at) {
                t.append('@');
                used_at = true;
                i += 2;
            } else {
                t.append(s.charAt(i));
                i++;
            }
        }
        System.out.println(t.toString());
        scanner.close();
    }
}
